export type Cell = [number, number];

const key = ([x, y]: Cell): string => `${x},${y}`;

export function nextGeneration(cells: Cell[]): Cell[] {
  const liveSet = new Set(cells.map(key));

  // Count how many live neighbours each candidate cell has, keeping the
  // candidate's coordinates alongside its count so no decoding is needed.
  const neighbours = new Map<string, { cell: Cell; count: number }>();
  for (const [x, y] of cells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        const cell: Cell = [x + dx, y + dy];
        const entry = neighbours.get(key(cell)) ?? { cell, count: 0 };
        entry.count++;
        neighbours.set(key(cell), entry);
      }
    }
  }

  // Reproduction: a dead cell with exactly 3 live neighbours becomes alive.
  const next: Cell[] = [];
  for (const { cell, count } of neighbours.values()) {
    if (count === 3 && !liveSet.has(key(cell))) {
      next.push(cell);
    }
  }
  return next;
}
